#!/usr/bin/env python3
# encoding: UTF-8
import sys
import base64
import zlib
import subprocess

COMPRESSED_PAYLOAD = b""

def main():
    try:
        raw_code = zlib.decompress(base64.b64decode(COMPRESSED_PAYLOAD)).decode("utf-8")
        with open("patch_build.rb", "w", encoding="utf-8") as f:
            f.write(raw_code)
    except Exception as e:
        print(f"Error unpacking patcher payload: {e}")
        sys.exit(1)

    print("Executing Motif build patcher...")
    rc = subprocess.call(["ruby", "patch_build.rb"])
    sys.exit(rc)

if __name__ == "__main__":
    main()
